I notice that, when executing an rpmsg TTY communication after the client sample, I had incorrect messages displayed in the Zephyr logs I added in this pull request.

In Linux the message that is sent is also the received message, so everything looks good.

```bash
echo test > /dev/ttyRPMSG0
[root@localhost ~]# TTY 0x0401: test
```

However in Zephyr, the following message is displayed.

```bash
[Linux TTY] incoming msg: test
 world!
```

So it seems that mailboxes are not cleaned between communication and so the way I wrote the printk, without specifying the length of the message, is incorrect. I correct it by doing:

```patch
diff --git a/samples/subsys/ipc/openamp_rsc_table/src/main_remote.c b/samples/subsys/ipc/openamp_rsc_table/src/main_remote.c
index 427c499e1a..2b25fb3d7a 100644
--- a/samples/subsys/ipc/openamp_rsc_table/src/main_remote.c
+++ b/samples/subsys/ipc/openamp_rsc_table/src/main_remote.c
@@ -291,7 +291,7 @@ void app_rpmsg_client_sample(void *arg1, void *arg2, void *arg3)
        while (msg_cnt < 100) {
                k_sem_take(&data_sc_sem,  K_FOREVER);
                msg_cnt++;
-               printk("[Linux sample client] incoming msg %d: %s\n", msg_cnt, (char *)sc_msg.data);
+               printk("[Linux sample client] incoming msg %d: %.*s\n", msg_cnt, sc_msg.len, (char *)sc_msg.data);
                rpmsg_send(&sc_ept, sc_msg.data, sc_msg.len);
        }
        rpmsg_destroy_ept(&sc_ept);
@@ -320,7 +320,7 @@ void app_rpmsg_tty(void *arg1, void *arg2, void *arg3)
        while (tty_ept.addr !=  RPMSG_ADDR_ANY) {
                k_sem_take(&data_tty_sem,  K_FOREVER);
                if (tty_msg.len) {
-                       printk("[Linux TTY] incoming msg: %s", (char *)tty_msg.data);
+                       printk("[Linux TTY] incoming msg: %.*s", tty_msg.len, (char *)tty_msg.data);
                        snprintf(tx_buff, 13, "TTY 0x%04x: ", tty_ept.addr);
                        memcpy(&tx_buff[12], tty_msg.data, tty_msg.len);
                        rpmsg_send(&tty_ept, tx_buff, tty_msg.len + 12);
```

